// Course data access. The JSON is generated by ../scripts/validate.js; never edit it by hand.
import data from "../data/courses.json";
import type { Course, Line, MoveNode } from "./types";

export const courses = data as unknown as Course[];

export function getCourse(id: string): Course | undefined {
  return courses.find((c) => c.id === id);
}

export function getLine(course: Course, lineId: string): Line | undefined {
  return course.lines.find((l) => l.id === lineId);
}

/** The tree nodes along a line, in order. */
export function lineNodes(course: Course, line: Line): MoveNode[] {
  const out: MoveNode[] = [];
  let level = course.tree;
  for (const san of line.sans) {
    const node = level.find((n) => n.san === san);
    if (!node) throw new Error(`Line ${course.id}/${line.id} leaves the tree at ${san}`);
    out.push(node);
    level = node.children;
  }
  return out;
}

/** Lines the user is drilled on: main lines plus alternatives. Warning lines are Learn-only. */
export function trainableLines(course: Course): Line[] {
  return course.lines.filter((l) => l.kind !== "warning");
}

/** "white" | "black" the user plays in this course. Trap collections ("both") are played as the winning side of each line. */
export function userColor(course: Course, line?: Line): "white" | "black" {
  if (course.side !== "both") return course.side;
  if (!line) return "white";
  return line.sans.length % 2 === 1 ? "white" : "black"; // the side that plays the final (mating/winning) move
}
